<template>
  <main class="nw-account">
    <header><router-link to="/fundthred/noteworthy"><NoteworthyBrand /></router-link><router-link to="/fundthred/noteworthy/demo">Explore the demo →</router-link></header>
    <div class="nw-account-grid">
      <section class="nw-account-story"><p class="eyebrow">The brains behind the pay</p><h1>Your next payroll starts here.</h1><p>Bring your TherapyNotes billing reports. Keep your payroll processor. Give your team a clear view of what they earned.</p><ol><li>Verify your account and create your practice.</li><li>Complete your practice agreements and secure data activation.</li><li>Upload a report, confirm rates, and follow the payroll wizard.</li></ol><div class="nw-trust"><strong>Connected by Auricwell.</strong><p>Practice access, protected records, and a guided setup before your first real billing report.</p></div></section>
      <section class="nw-account-card" aria-live="polite">
        <p v-if="error" class="nw-alert nw-alert-error" role="alert">{{ error }}</p><p v-if="message" class="nw-alert" role="status">{{ message }}</p>
        <template v-if="mode === 'verify'"><h2>{{ verified ? 'Email verified. You’re ready to sign in.' : 'Verify your email' }}</h2><p>{{ verified ? 'Your account is ready. Sign in through the secure account flow to open your payroll workspace.' : 'Confirm the email address used for your NoteWorthy account.' }}</p><form v-if="!verified && token" @submit.prevent="verify"><label v-if="verifyNeedsPassword">Choose your account password<input v-model="form.password" required type="password" minlength="12" maxlength="72" autocomplete="new-password" /><small>Use at least 12 characters. This password is set only after you open your email verification link.</small></label><button class="nw-submit" :disabled="busy">{{ busy ? 'Verifying…' : verifyNeedsPassword ? 'Set password & verify account' : 'Verify my email' }}</button></form><router-link v-if="verified || !token" class="nw-submit" :to="signIn">Sign in to NoteWorthy →</router-link></template>
        <template v-else-if="mode === 'invite'"><h2>{{ verified ? 'Your payroll portal is ready.' : 'Your personal payroll portal' }}</h2><p>See your own posted statements, service codes, and pay details.</p><form v-if="!verified && token" @submit.prevent="acceptInvite"><label v-if="!auth.isAuthenticated || inviteNeedsPassword">Password for a new account<input v-model="form.password" type="password" autocomplete="new-password" minlength="12" maxlength="72" /><small>Already have an account? Sign in first, then reopen this invitation from your email.</small></label><button class="nw-submit" :disabled="busy">{{ busy ? 'Accepting…' : 'Accept invitation' }}</button></form><button v-if="wrongInviteAccount" type="button" @click="switchInviteAccount">Sign out and use the invited account</button><router-link class="nw-text-link" :to="signIn">{{ verified ? 'Open my payroll portal →' : 'Sign in to my existing account →' }}</router-link></template>
        <template v-else-if="requested"><h2>Check your email.</h2><p>We saved your account request. Use your verification email to finish setting up your practice.</p><button :disabled="busy" class="nw-submit" @click="resend">Resend verification</button><router-link class="nw-text-link" :to="signIn">Already verified? Sign in →</router-link></template>
        <form v-else @submit.prevent="signup"><p class="eyebrow">{{ auth.isAuthenticated ? 'Add a practice' : 'Create your workspace' }}</p><h2>Make payroll NoteWorthy.</h2><label>Practice name<input v-model="form.practiceName" required maxlength="160" autocomplete="organization" /></label><div v-if="!auth.isAuthenticated" class="nw-form-pair"><label>First name<input v-model="form.firstName" required maxlength="100" autocomplete="given-name" /></label><label>Last name<input v-model="form.lastName" required maxlength="100" autocomplete="family-name" /></label></div><template v-if="!auth.isAuthenticated"><label>Work email<input v-model="form.email" required type="email" maxlength="254" autocomplete="email" /></label></template><label>Your plan<select v-model="form.plan"><option value="essential">Essential · $79/month · up to 10 team members</option><option value="growth">Growth · $149/month · up to 25 team members</option><option value="enterprise">Enterprise · from $299/month · 25+ team members</option></select></label><p class="nw-small">Your plan preference is saved for onboarding. No payment is collected here.</p><button class="nw-submit" :disabled="busy">{{ busy ? 'Saving…' : auth.isAuthenticated ? 'Create practice workspace →' : 'Create my account →' }}</button><p class="nw-small">Read the <a href="https://auricwell.com/auricwell/terms" target="_blank" rel="noopener noreferrer">platform terms</a> and <a href="https://auricwell.com/auricwell/privacypolicy" target="_blank" rel="noopener noreferrer">privacy policy</a>. Practice agreements are completed separately before billing-report uploads.</p><button v-if="needsVerification" type="button" :disabled="busy" @click="requestVerification">Send account verification email</button><router-link v-if="!auth.isAuthenticated" class="nw-text-link" :to="signIn">Already have an account? Sign in →</router-link></form>
      </section>
    </div>
  </main>
</template>
<script setup>
import { computed, onBeforeUnmount, reactive, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { useAuthStore } from '../../store/auth';
import api from '../../services/api';
import { enterPublicAuthForm } from '../../utils/publicAuthForm';
import { fundthredLoginLocation } from '../../utils/fundthred';
import NoteworthyBrand from '../../components/noteworthy/NoteworthyBrand.vue';
import '../../styles/noteworthyPayroll.css';
import '../../styles/noteworthyWorkspace.css';
const route=useRoute(),router=useRouter(),auth=useAuthStore();
const leaveAuth=enterPublicAuthForm();onBeforeUnmount(leaveAuth);
const mode=computed(()=>route.name==='NoteworthyVerify'?'verify':route.name==='NoteworthyInvite'?'invite':'signup');
const token=ref(new URLSearchParams(String(route.hash || '').replace(/^#/, '')).get('token') || '');
// Verification secrets stay in memory and never enter request logs or local storage.
if(token.value && typeof window!=='undefined') window.history.replaceState(window.history.state,'',window.location.pathname+window.location.search);
const form=reactive({practiceName:'',firstName:'',lastName:'',email:'',password:'',plan:['essential','growth','enterprise'].includes(route.query.plan)?route.query.plan:'essential'});
const verifyNeedsPassword=ref(false);
const inviteNeedsPassword=ref(false),wrongInviteAccount=ref(false);
const busy=ref(false),error=ref(''),message=ref(''),requested=ref(false),verified=ref(false),needsVerification=ref(false);
const config={headers:{'X-Noteworthy-Request':'1'},skipGlobalLoading:true};
const signIn=fundthredLoginLocation('/fundthred/noteworthy/app');
async function run(fn){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn();}catch(e){error.value=e.response?.data?.error?.message || 'We could not complete that request. Please try again.';needsVerification.value=e.response?.data?.error?.code==='EMAIL_VERIFICATION_REQUIRED';inviteNeedsPassword.value=e.response?.data?.error?.code==='PASSWORD_REQUIRED';wrongInviteAccount.value=e.response?.data?.error?.code==='EXISTING_ACCOUNT_SIGN_IN_REQUIRED';if(e.response?.data?.error?.code==='VERIFICATION_PENDING')requested.value=true;}finally{busy.value=false;}}
function signup(){return run(async()=>{if(auth.isAuthenticated){const {data}=await api.post('/noteworthy/practices',{practiceName:form.practiceName,plan:form.plan},config);await router.push(`/fundthred/noteworthy/app/${data.agencyId}`);}else{const {data}=await api.post('/noteworthy/signup',{practiceName:form.practiceName,firstName:form.firstName,lastName:form.lastName,email:form.email,plan:form.plan},config);form.password='';requested.value=true;message.value=data.message || 'Check your email to verify your account.';}});}
function verify(){return run(async()=>{const {data}=await api.post('/noteworthy/verify',{token:token.value,...(verifyNeedsPassword.value?{password:form.password}:{})},config);if(data.passwordRequired){verifyNeedsPassword.value=true;message.value='Choose your password to finish creating your verified account.';return;}if(data.signInRequired && auth.isAuthenticated)await auth.logout();token.value='';form.password='';verified.value=true;});}
function acceptInvite(){return run(async()=>{const {data}=await api.post('/noteworthy/accept-invite',{token:token.value,...(form.password?{password:form.password}:{})},config);if(data.signInRequired && auth.isAuthenticated)await auth.logout();token.value='';form.password='';verified.value=true;});}
async function switchInviteAccount(){await auth.logout();await router.push(signIn);}
function resend(){return run(async()=>{message.value=(await api.post('/noteworthy/resend-verification',{email:form.email},config)).data.message;});}
function requestVerification(){return run(async()=>{const {data}=await api.post('/noteworthy/request-account-verification',{},config);message.value=data.verificationSent?'Verification email sent. Verify, then return here.':'Verification requested. Email delivery has not yet been confirmed.';});}
</script>
